L=[['拉丁 labi；分词 lapsus','滑动、滑落、跌下']]
CO=L+[['拉丁 com- + labi → collabi；分词 collapsus','一起落下、失去支撑而塌下'],['英语 collapse','坍塌、倒下；也指计划或体系失败，随后用作名词']]
EL=L+[['拉丁 ex- + labi → elabi；分词 elapsus','滑走、流逝'],['法语 elapser → 英语 elapse','尤其指一段时间过去']]
W=[
E('collapse','英、美 /kəˈlæps/','坍塌；倒下；崩溃、失败；折叠收起；坍塌、崩溃这一事件','原先撑着的东西失去支撑，一下塌下来。谈判、市场或计划失去关键支持，也可以比喻成塌掉。','接拉丁 collapsus，来自 collabi：com-“一起”在此成为 col-，labi 是滑落、跌下。常用英语名词由动词发展，不是从现代 lapse 随便加一个 col-。',CO,'a roof collapses 是屋顶坍塌；talks collapse 是谈判破裂；collapse a table 是把可折叠桌收起来。电脑界面的 collapse a section 则是收起这一栏，并不是程序崩溃。','a building collapse；talks collapse；collapse from exhaustion；collapse a section。','fall 范围很广；collapse 通常强调失去支撑、力量或结构。界面里的 collapse 与 expand 相对，crash 才常说程序意外崩溃。',('The old shed collapsed during the storm.','旧棚屋在暴风雨中倒塌了。'),('The negotiations collapsed after both sides rejected the proposal.','双方拒绝提案后，谈判破裂了。'),('Click the arrow to collapse the section.','点击箭头收起这一部分。'),sources=[S('collapse'),K('collapse'),O('collapse_1'),O('collapse_2')]),
E('collapsed','英、美 /kəˈlæpst/','倒塌了；已经崩溃的；已折叠、已收起的','动作完成后的样子：屋顶塌了，合作失败了，或菜单内容收起来了。','现代常用形式是 collapse + -ed，末尾读 /t/，整个结尾是 /pst/。历史上更早还存在 collapsed 的其他形容词用法，不能把当前构词分析当成所有旧记录的唯一来源。',CO+[['现代英语 collapse + -ed → collapsed','倒塌、失败或收起后的状态']],'a collapsed roof 指塌下的屋顶；a collapsed menu 指内容被收起的菜单。不能看见 collapsed 就断定出了故障，软件界面中它常是正常的显示状态。','a collapsed building；collapsed negotiations；a collapsed section；collapsed under pressure。','collapsible 是能够折叠，collapsed 是已经折叠或塌下。一把设计正常的 collapsible chair 可以安全折叠收起，以便收纳。',('The collapsed roof blocked the entrance.','倒塌的屋顶堵住了入口。'),('The details remain hidden in the collapsed panel.','详细信息仍隐藏在收起的面板中。'),sources=[S('collapse'),K('collapsed'),O('collapse_1')]),
E('collapsible','英、美 /kəˈlæpsəbəl/','可折叠的；可收缩的','设计时就让它能缩小、收起来，方便携带或存放。这里的“塌”是可控制的结构变化，不一定是坏掉。','英语 collapse + -ible，去掉末尾 e；历史也有 collapsable 的拼法。这个后缀表示能够发生这种变化。',CO+[['英语 collapse + -ible → collapsible','可收起、可折叠的']],'a collapsible chair 可以折起来；a collapsible water bottle 可以压缩后装包。网页的 collapsible section 是能展开、收起的内容区域。','a collapsible chair；a collapsible container；a collapsible section。','collapsed 是现在已经收起或塌了；collapsible 是具备收起能力。foldable 很接近，通常突出折叠动作。',('The collapsible table fits behind the cupboard.','这张可折叠桌收起来后能放在柜子后面。'),('The guide uses collapsible sections for the detailed explanations.','指南把详细说明放在可以展开、收起的分区里。'),sources=[S('collapsible'),K('collapsible'),O('collapsible')]),
E('lapse','英、美 /læps/','一时疏忽、失误；间隔；失效；陷入某种状态','事情没接稳，短暂滑了一下：注意力走神、记忆漏掉；原本有效的资格也可能因为没有续办而失效。','名词经法语 laps，接拉丁 lapsus“滑落、时间流逝、出错”。动词与英语名词以及拉丁 lapsare“滑动”都有来源联系；不把所有词性硬归成一个现代派生方向。',L+[['拉丁 lapsus／lapsare；法语 laps','滑落、流逝、出错的名词与动词支线'],['中古英语 lapse 名词、动词','疏忽、间隔；时间过去、失效或滑入某种状态']],'a lapse in concentration 是一时走神；a memory lapse 是一时记不起来；membership lapses 是会员资格失效。lapse into silence 是渐渐不说话，滑入沉默。','a lapse in judgment；a memory lapse；let membership lapse；lapse into silence。','elapse 通常只说时间过去；lapse 的常见范围更广，还说疏忽、失效。relapse 则是回到原先不好的状态。',('A brief lapse in concentration made me miss the turn.','我一时走神，错过了转弯。'),('Her membership lapsed when she forgot to renew it.','她忘了续费，会员资格便失效了。'),('After a few polite remarks, they lapsed into silence.','客套几句后，他们陷入了沉默。'),sources=[S('lapse'),K('lapse'),O('lapse_1'),O('lapse_2')]),
E('relapse','名词英、美 /ˈriːlæps/；动词 /rɪˈlæps/，美式也读 /ˈriːlæps/','复发；重犯旧习；重新陷入较差状态','已经好转或离开旧习惯，却又退回去。关键是先有改善，再出现回落。','接拉丁 relapsus，来自 re-“回去”+ labi“滑落”的 relabi。名词既有英语动词转用的分析，也有中世纪拉丁名词来源分析，不能把所有用法只讲成现代 re- + lapse。',L+[['拉丁 re- + labi → relabi；分词 relapsus','滑回、退回原状态'],['英语 relapse 动词；名词也有中世纪拉丁支线','回到旧状态；随后广用于疾病或症状复发']],'have a relapse 是出现复发；relapse into old habits 是重拾旧习。医疗用词关注病情变化，并不表示对一个人的道德评判。名词常重读开头，动词常重读后半。','have a relapse；suffer a relapse；relapse into old habits；a risk of relapse。','recurrence 广泛说再次出现；relapse 常带曾经改善后又回落的意思。lapse 可以只是一次疏忽，不一定表示回到旧状态。',('After several better weeks, he experienced a relapse.','好转了几个星期后，他又出现了复发。'),('Under pressure, she relapsed into her old habit of skipping breaks.','压力一大，她又回到从不休息的老习惯。'),sources=[S('relapse'),K('relapse'),O('relapse_1'),O('relapse_2')]),
E('elapse','英、美 /ɪˈlæps/','〔时间〕过去；流逝','像时间从身旁滑走：一开始是现在，回头看已经过了几分钟或几年。','经法语 elapser，接拉丁 elapsus，来自 ex-“离开”+ labi“滑动”的 elabi。现代开头的 e- 在这条来源里接 ex-，不是电子 e-。',EL,'Ten minutes elapsed 是十分钟过去了，通常由时间作主语。它是不及物动词；不说 I elapsed ten minutes 来表示我花了十分钟。','time elapses；minutes elapse；before much time has elapsed。','spend 是人花费时间，elapse 是时间自己过去。Ten minutes elapsed 与 I spent ten minutes 表达视角不同。',('Twenty minutes elapsed before the next bus arrived.','过了二十分钟，下一班公交车才来。'),('Several years had elapsed since their last meeting.','距离他们上次见面已经过去好几年了。'),sources=[S('elapse'),K('elapse'),O('elapse')]),
E('elapsed','英、美 /ɪˈlæpst/','已过去的；已流逝的','从起点算到现在，已经过去多少时间。计时器上的 elapsed time 就是在回答这个问题。','英语 elapse + -ed，末尾读 /t/，不是额外读出 /ɪd/。既可作过去式，也常修饰 time。',EL+[['英语 elapse + -ed → elapsed','已经流逝；从起点经过的时间']],'elapsed time 是经过的总时间；time remaining 是剩余时间。程序报告中的 elapsed time 通常看钟表上经过多久，不一定等于处理器真正工作了多久。','elapsed time；the time elapsed；minutes elapsed。','elapsed 是已经过去，remaining 是还剩下；lapsed 常表示已经失效，如 a lapsed subscription。',('The timer displays elapsed time in minutes and seconds.','计时器以分、秒显示已过去的时间。'),('Only two minutes had elapsed when the phone rang again.','仅过了两分钟，电话又响了。'),sources=[K('elapsed'),S('elapse'),O('elapse')]),
E('prolapse','名词英 /ˈprəʊlæps/；美 /ˈproʊlæps/','〔医学〕脱垂；器官或组织离开正常位置的下移、突出','原本被支撑在适当位置的器官或组织，向下或向外移位。具体移到哪里，要看说的是哪个部位。','接拉丁 prolapsus，来自 pro-“向前、向外”+ labi“滑动”的 prolabi。英语医学用法先有滑落的动词记录，名词也承接这条拉丁词族。',L+[['拉丁 pro- + labi → prolabi；分词 prolapsus','向前或向下滑出'],['英语医学词 prolapse','器官、组织下移或突出原有位置']],'pelvic organ prolapse 指盆腔器官脱垂；rectal prolapse 是直肠脱垂。prolapse 描述位置、支撑方面的变化，不是一个词就说明所有人的原因或严重程度。','pelvic organ prolapse；rectal prolapse；a diagnosis of prolapse。','relapse 是好转后复发，prolapse 是器官或组织移位。两者都带 laps-，医疗含义却不同。',('The leaflet explains pelvic organ prolapse with a simple diagram.','说明单用一张简单示意图解释盆腔器官脱垂。'),('The doctor clarified the meaning of prolapse in the report.','医生说明了报告中 prolapse 这个词的含义。'),sources=[S('prolapse'),K('prolapse'),'https://www.nhs.uk/conditions/pelvic-organ-prolapse/','https://www.nhsinform.scot/illnesses-and-conditions/sexual-and-reproductive/pelvic-organ-prolapse']),
E('lava','英、美 /ˈlɑːvə/','熔岩；熔岩凝固后形成的岩石','火山里的熔融岩石来到地表，流动时是熔岩；冷却凝固后，这个名称也可保留下来指形成的岩石。','从意大利语 lava 借入，地方用语原可指暴雨形成的急流，再用于火山流出的熔岩。更早来源有拉丁 labes“坠落、崩落”的分析，也有传统 lavare“洗”说；这里保留分歧，不把未知部分画成确定祖先。',[['意大利地方用语 lava','暴雨后形成的急流；远源有不同分析'],['意大利语 lava 的火山用法','像流体一样涌出的熔融岩石；也指凝固后的岩石'],['英语 lava','火山熔岩及其冷却形成的岩石']],'a lava flow 是熔岩流；hardened lava 是凝固的熔岩。和地下的 magma 对比时，区别主要在是否已到地表，而不是只看有没有红光或冒烟。','a lava flow；molten lava；hardened lava；a lava field。','magma 是地下的岩浆，lava 是喷出或流到地表的熔岩。lava 和 lavatory 的字母相近，也不能据此断言同出“洗”。',('A stream of lava moved slowly down the slope.','一股熔岩沿山坡缓慢流下。'),('The coast is covered with dark, hardened lava.','海岸覆盖着深色的凝固熔岩。'),sources=[S('lava'),K('lava'),'https://ahdictionary.com/word/search.html?q=lava','https://volcano.wr.usgs.gov/volcanic_ash/glossary/lava.html','https://www.usgs.gov/programs/VHP/about-volcanoes']),
]
SHARED=[]
EX={'labile':'多见于化学稳定性、医学情绪等专门讨论，按用户常用优先要求暂略。'}
ROOT=dict(id='C0639',meaning='滑动；滑落、跌下',core='拉丁 labi 是滑动、滑落，lapsus 是相关分词形式。东西滑下会塌，时间滑走会流逝，状态滑回去会复发。',image='一起落下 → collapse；短暂失手或失效 → lapse；滑回旧状态 → relapse；时间滑走 → elapse；器官向下或向外移位 → prolapse。lava 的可靠路线从意大利急流名称起，更早同源仍有分歧。',intro='先用支撑失去、时间流走、状态退回这三种场景记主要词。它们共享滑动意象，现代用法却不同：不能拿 elapse 表示花时间，也不能把 prolapse 当作 relapse。',forms='labi 是拉丁动词形式，lapsus 带出常见 laps-。collapse 的 col- 来自 com-，relapse 的 re- 表回去，elapse 的 e- 接 ex-，prolapse 的 pro- 表向前、向外。lava 可与拉丁 labes 来源分析一起了解，但不作为无争议的直系后代。',branches=[['失去支撑或折叠收起','collapse, collapsed, collapsible'],['疏忽、失效与回到旧状态','lapse, relapse'],['时间流逝','elapse, elapsed'],['医学上的移位','prolapse'],['意大利急流到火山熔岩','lava']],contrasts='collapse 是塌下或失败，collapsible 是设计成可折叠；lapse 可说疏忽、失效，elapse 通常说时间过去；relapse 是复发，prolapse 是脱垂。lava 与本根的更早关系保留来源分歧。',practice='Ten minutes elapsed before the talks collapsed. 十分钟过去后，谈判破裂了：时间流逝与事情失去支撑，是同一个老画面的不同发展。',words=[],exclude=EX)
